import React, { useEffect, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import CountUp from 'react-countup';
import { useScrollReveal } from '../hooks/useScrollReveal';
import ParticleField from '../components/common/ParticleField';
import { vehicles } from '../utils/vehicleData';
import './Home.css';

const marqueeItems = [
  'Mercedes-Benz','Porsche','AMG','Taycan','EQS','911 Carrera',
  'Luxe','Performance','Innovation','Électrique','Prestige','Excellence'
];

/* =================== HERO =================== */
function HeroSection() {
  // FIX : force le re-render après mount pour déclencher les animations CSS
  const [mounted, setMounted] = useState(false);
  useEffect(() => {
    const t = setTimeout(() => setMounted(true), 50);
    return () => clearTimeout(t);
  }, []);

  return (
    <section className="hero">
      <div className="hero__bg" />
      <ParticleField count={60} />
      <div className="hero__grid-lines" />
      <div className="hero__scanline" />
      <video className="hero__video" autoPlay muted loop playsInline>
        <source src="/videos/hero.mp4" type="video/mp4" />
      </video>
      <div className="hero__overlay" />

      <div className="hero__content">
        <div className="hero__eyebrow">
          <div className="hero__eyebrow-line" />
          <span className="section-label">Concessionnaire Officiel · Paris</span>
        </div>

        <h1 className="hero__title">
          <span className="hero__title-row">
            <span className="hero__title-word">L'Art</span>
          </span>
          <span className="hero__title-row">
            <span className="hero__title-word">de l'Excellence</span>
          </span>
          <span className="hero__title-row">
            <span className="hero__title-word">Automobile</span>
          </span>
        </h1>

        <p className="hero__subtitle">
          Mercedes-Benz · Porsche · Une sélection exclusive de véhicules d'exception,
          pensés pour les esprits les plus exigeants.
        </p>

        {/* FIX : les boutons sont toujours dans le DOM, l'animation CSS gère l'apparition */}
        <div className="hero__actions">
          <Link to="/vehicles" className="btn-gold">
            <span>Explorer la collection</span>
            <span>→</span>
          </Link>
          <Link to="/contact" className="hero__link">
            Prendre rendez-vous <span>→</span>
          </Link>
        </div>
      </div>

      <div className="hero__scroll">
        <div className="hero__scroll-mouse">
          <div className="hero__scroll-wheel" />
        </div>
        <span className="hero__scroll-text">Défiler</span>
      </div>

      <div className="hero__stats">
        {[
          { end: 20,   suffix: '+',  label: "Années d'expertise" },
          { end: 1000, suffix: '+',  label: 'Clients satisfaits' },
          { end: 50,   suffix: '+',  label: 'Modèles disponibles' },
          { end: 4.9,  suffix: '★', decimals: 1, label: 'Note moyenne' },
        ].map(s => (
          <div key={s.label} className="hero__stat">
            <span className="hero__stat-value">
              <CountUp
                end={s.end}
                suffix={s.suffix}
                decimals={s.decimals || 0}
                duration={2.5}
                enableScrollSpy
                scrollSpyOnce
              />
            </span>
            <span className="hero__stat-label">{s.label}</span>
          </div>
        ))}
      </div>
    </section>
  );
}

/* =================== MARQUEE =================== */
function MarqueeSection() {
  const items = [...marqueeItems, ...marqueeItems];
  return (
    <div className="marquee-section">
      <div className="marquee-track">
        {items.map((item, i) => (
          <div key={i} className="marquee-item">
            <span className="marquee-dot" />
            {item}
          </div>
        ))}
      </div>
    </div>
  );
}

/* =================== BRAND =================== */
function BrandSection() {
  const [ref, visible] = useScrollReveal();

  return (
    <section className="brand-section">
      <div className="container">
        <div
          ref={ref}
          className={`brand-section__inner reveal-up ${
            visible ? 'visible' : ''
          }`}
        >
          <div>
            <span className="section-label">Nos Marques Partenaires</span>

            <h2 className="brand-section__title">
              Deux légendes,<br />
              <em>une seule passion</em>
            </h2>

            <p className="brand-section__text">
              Depuis deux décennies, Luxury Auto représente l'élite de
              l'automobile mondiale. Chaque véhicule est une promesse
              d'excellence, de raffinement et de performance absolue.
            </p>

            <Link to="/about" className="hero__link">
              Découvrir notre histoire <span>→</span>
            </Link>
          </div>

          <div className="brand-section__logos">

            {/* MERCEDES */}
            <div className="brand-logo-card">
              <div className="brand-logo-card__logo-wrap">
                <img
                  src="/logos/mercedes.png"
                  alt="Mercedes-Benz"
                  className="brand-logo-card__logo"
                />
              </div>

              <span className="brand-logo-card__name">
                Mercedes-Benz
              </span>

              <span className="brand-logo-card__tagline">
                The Best or Nothing
              </span>

              <div className="brand-logo-card__glow" />
            </div>

            {/* PORSCHE */}
            <div className="brand-logo-card">
              <div className="brand-logo-card__logo-wrap">
                <img
                  src="/logos/porsche.png"
                  alt="Porsche"
                  className="brand-logo-card__logo"
                />
              </div>

              <span className="brand-logo-card__name">
                Porsche
              </span>

              <span className="brand-logo-card__tagline">
                There is no substitute
              </span>

              <div className="brand-logo-card__glow" />
            </div>

          </div>
        </div>
      </div>
    </section>
  );
}
function VehicleCard({ vehicle, index }) {
  const [ref, visible] = useScrollReveal();

  return (
    <div
      ref={ref}
      className={`vehicle-card ${visible ? 'reveal' : ''}`}
      style={{ transitionDelay: `${index * 0.15}s` }}
    >
      <div
        className="vehicle-card__visual"
        style={{ background: vehicle.color }}
      >

        {/* IMAGE VEHICULE */}
        <img
          src={vehicle.image}
          alt={vehicle.model}
          className="vehicle-card__image"
        />

        {vehicle.isElectric && (
          <span className="vehicle-card__badge">
            EV
          </span>
        )}

        {vehicle.isNew && (
          <span className="vehicle-card__badge vehicle-card__badge--new">
            Nouveau
          </span>
        )}

        <div
          className="vehicle-card__overlay"
          style={{
            background: `linear-gradient(to top, ${vehicle.color}, transparent)`
          }}
        />
      </div>

      <div className="vehicle-card__info">
        <div className="vehicle-card__meta">
          <span className="vehicle-card__category">
            {vehicle.category}
          </span>

          <span
            className="vehicle-card__power"
            style={{ color: vehicle.accent }}
          >
            {vehicle.power}
          </span>
        </div>

        <h3 className="vehicle-card__name">
          {vehicle.brand} {vehicle.model}
        </h3>

        <p className="vehicle-card__tagline">
          {vehicle.tagline}
        </p>

        <div className="vehicle-card__specs">
          <span>0-100: {vehicle.acceleration}</span>
          <span>{vehicle.fuel}</span>
          <span>Vmax: {vehicle.speed}</span>
        </div>

        <div className="vehicle-card__footer">
          <span className="vehicle-card__price">
            Dès {vehicle.price} €
          </span>

          <Link
            to={`/vehicles/${vehicle.id}`}
            className="vehicle-card__link"
            style={{ color: vehicle.accent }}
          >
            Découvrir →
          </Link>
        </div>
      </div>
    </div>
  );
}

/* =================== EXPERIENCE =================== */
function ExperienceSection() {
  const [ref, visible] = useScrollReveal();
  return (
    <section className="experience-section">
      <div ref={ref} className={`experience-section__inner reveal-up ${visible ? 'visible' : ''}`}>
        <div>
          <span className="section-label">Votre Expérience</span>
          <h2 className="experience-section__title">
            Un service à la<br />
            <em className="shimmer-text">hauteur de l'exception</em>
          </h2>
          <p className="experience-section__text">
            De la première visite à la livraison de votre véhicule, chaque étape est
            orchestrée avec soin par nos conseillers spécialisés.
          </p>
          <Link to="/contact" className="btn-gold" style={{ marginTop: 40, display: 'inline-flex' }}>
            <span>Prendre rendez-vous</span>
          </Link>
        </div>

        <div className="experience-section__services">
          {[
            { icon: '🎯', title: 'Configuration sur mesure',  desc: 'Personnalisez chaque détail selon vos désirs les plus exigeants.' },
            { icon: '🏎', title: 'Essai routier privé',        desc: "Vivez l'expérience sur circuit ou route ouverte, avant l'achat." },
            { icon: '💎', title: 'Livraison Premium',          desc: 'Cérémonie de remise des clés dans notre showroom privé.' },
            { icon: '🔧', title: 'Après-vente VIP',            desc: 'Prise en charge à domicile et véhicule de courtoisie offert.' },
          ].map(s => (
            <div key={s.title} className="service-card">
              <span className="service-card__icon">{s.icon}</span>
              <h4 className="service-card__title">{s.title}</h4>
              <p className="service-card__desc">{s.desc}</p>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

/* =================== CTA =================== */
function CTASection() {
  const [ref, visible] = useScrollReveal();
  return (
    <section className="cta-section">
      <div className="cta-section__glow" />
      <div ref={ref} className={`cta-section__inner reveal-up ${visible ? 'visible' : ''}`}>
        <span className="section-label">Rejoignez l'Excellence</span>
        <h2 className="cta-section__title">
          Prêt à vivre<br />l'expérience<br />
          <em className="shimmer-text">Luxury Auto ?</em>
        </h2>
        <div className="gold-line" style={{ margin: '28px auto' }} />
        <p className="cta-section__text">
          Créez votre espace client exclusif et accédez à des privilèges réservés aux membres.
        </p>
        <div className="cta-section__actions">
          <Link to="/register" className="btn-gold">
            <span>Créer mon espace client</span>
          </Link>
          <Link to="/vehicles" className="btn-white">
            <span>Explorer les véhicules</span>
          </Link>
        </div>
      </div>
    </section>
  );
}

/* =================== PAGE =================== */
export default function Home() {
  return (
    <main className="home">
      <HeroSection />
      <MarqueeSection />
      <BrandSection />
      <VehiclesSection />
      <ExperienceSection />
      <CTASection />
    </main>
  );
}
